// Independent auditor D13 engine probe (Bun, development-only, no database).
// A: random games, compiled bridge (timed, limit 10) vs raw unchanged-core MatchRuntime vs untimed bridge.
// B: main-game timeout == the engine's own late passTurn (D14 restore, bonuses, events, full state).
// C: whole-game limit (non-consecutive and consecutive), natural-end precedence.
// D: opening timeouts at all three decisions; E: opening concessions by either player.
// F: players cannot reach forfeitGame or concede for the opponent; G/H: controls and pauses.
// I: private replay of both endings and tamper rejection.
import assert from 'node:assert/strict';
import { randomBytes, createHash } from 'node:crypto';
const ROOT = '/workspaces/lorcana-online-tcg/';
const U = ROOT + 'vendor/tcg-engines/upstream/submodules/lorcana/packages/lorcana/lorcana-engine/src/';
const { createSyntheticKernel, KERNEL_IDENTITY } = await import(ROOT + 'vendor/tcg-engines/dist/kernel.js');
const { createRandomSource } = await import(ROOT + 'packages/engine-adapter/dist/random.js');
const { createRecordedCore, canonical } = await import(ROOT + 'packages/engine-adapter/dist/replay.js');
const { verifyCompletedReplay } = await import(ROOT + 'packages/engine-adapter/dist/index.js');
const { MatchRuntime } = await import(U + 'core/runtime/match-runtime.ts');
const { lorcanaRuntimeConfig } = await import(U + 'runtime-game/definition.ts');
const { createRecordCardCatalog } = await import(U + 'core/runtime/static-resources.ts');
const { createPlayerId } = await import(U + 'core/types/branded-utils.ts');

const NATIVE = { initialReserveMs: 150000, reserveCapMs: 150000, perActionBonusMs: 5000, perTurnPassBonusMs: 60000, resetTimeOnSkipMs: 60000, graceMs: 0 as const };
const players: [string, string] = ['p1', 'p2'];
const other = (p: string) => (p === 'p1' ? 'p2' : 'p1');
const clone = (v: unknown) => JSON.parse(JSON.stringify(v));
const out: Record<string, unknown> = {};

function rawRuntime(seed: Buffer, context: string, start: number, clock?: typeof NATIVE) {
  const source = createRandomSource(seed, context);
  let now = start;
  const identity = (domain: string, index: number) => domain + '-' + source.identifier(domain, index);
  const definitions = Object.fromEntries(players.map((_, index) => {
    const id = 'synthetic-' + index;
    return [id, { id, canonicalId: 'ci_' + id, slug: id, printings: [], cardType: 'character', name: 'Synthetic character ' + index, cost: 1, inkType: ['amber'], inkable: true, strength: 1, willpower: 2, lore: 1, classifications: ['Storyborn'], set: 'TST', rarity: 'common', abilities: [], i18n: { en: { name: 'Synthetic character ' + index } }, cardNumber: index + 1 }];
  }));
  const owners = Object.fromEntries(players.map((id, pi) => [id, Array.from({ length: 12 }, (_, i) => identity('instance', pi * 12 + i))]));
  const cardInstances = Object.fromEntries(players.flatMap((id, i) => owners[id].map((inst: string) => [inst, 'synthetic-' + i])));
  const runtime = new MatchRuntime({ ...lorcanaRuntimeConfig, ...(clock ? { timeControl: { mode: 'dynamic', config: { ...clock } } } : {}), randomSource: source, now: () => now, rulesetIdentity: KERNEL_IDENTITY } as never,
    { players: players.map(id => ({ id: createPlayerId(id) })), seed: 'project-injected', matchID: identity('match', 0), gameID: identity('game', 0), cardCatalog: createRecordCardCatalog('synthetic-rule-03', definitions), cardsMaps: { owners, cardInstances }, capturePatches: false } as never);
  return {
    runtime,
    state: () => clone(runtime.getState()),
    submit(actor: string, timestamp: number, commandId: string, move: string, input: Record<string, unknown>) {
      const args = move === 'chooseWhoGoesFirst' ? input : { ...input, playerId: actor };
      now = timestamp;
      const r = runtime.processCommand({ commandID: commandId, move, input: { args } } as never, actor, runtime.getCurrentStateID(), timestamp, 'player');
      return { accepted: r.success, code: r.success ? null : (r as { errorCode?: string }).errorCode ?? 'REJECTED' };
    },
  };
}
const kernel = (seed: Buffer, context: string, start: number, limit?: number) =>
  createSyntheticKernel({ randomSource: createRandomSource(seed, context), players, startTimestamp: start, ...(limit ? { clock: { ...NATIVE, timeoutLimit: limit } } : {}) });
const withoutTime = (state: any) => { const s = clone(state); delete s.ctx.time; delete s.ctx.rulesetHash; return s; };
const zones = (state: any) => state.ctx.zones.private.zoneCards;
const rem = (k: any, p: string) => k.clock().players.find((x: any) => x.playerId === p).remainingMs;
const count = (k: any, p: string) => k.clock().players.find((x: any) => x.playerId === p).timeoutCount;
const deadline = (k: any) => { const c = k.clock(); return c.startedAtMs + rem(k, c.activePlayerId); };

let lcg = 0x2026_1020;
const rand = (n: number) => { lcg = (Math.imul(lcg, 1103515245) + 12345) >>> 0; return (lcg >>> 16) % n; };
function pick<T>(a: T[]): T | undefined { return a.length ? a[rand(a.length)] : undefined; }
const GAPS = [0, 1, 250, 999, 4999, 5000, 59999, 60000, 124999, 125000, 125001, 149999, 150000, 150001, 210000];

// ---------- A: random parity ----------
const A = { openingLateForfeits: 0, games: 0, commands: 0, accepted: 0, rejected: 0, fullStateEqualAfterAccept: 0, ctxTimeDivergenceOnReject: 0, openingConcessions: 0, negativePasses: 0, forfeitsAtLimit10: 0, endReasons: {} as Record<string, number>, codes: {} as Record<string, number> };
function playGame(gameIndex: number) {
  const seed = randomBytes(32), context = 'audit-d13-parity-' + gameIndex, start = 1_000_000 + gameIndex;
  const T = kernel(seed, context, start, 10), N = kernel(seed, context, start), R = rawRuntime(seed, context, start, NATIVE);
  assert.deepEqual(T.snapshot(), R.state(), 'initial timed bridge/raw state');
  let ts = start, n = 0, stop = false;
  const submitAll = (actor: string, move: string, input: Record<string, unknown>) => {
    ts += T.snapshot().ctx.status.gameSegment === 'startingAGame' && rand(8) !== 0 ? pick([0, 1, 250, 4999, 60000])! : pick(GAPS)!;
    const id = 'g' + gameIndex + '-c' + n++;
    const before = T.clock(), wasOpening = T.snapshot().ctx.status.gameSegment === 'startingAGame';
    const t = T.submit(actor, T.status().revision, ts, id, move, clone(input));
    const u = N.submit(actor, N.status().revision, ts, id, move, clone(input));
    const r = R.submit(actor, ts, id, move, clone(input));
    A.commands++;
    assert.equal(t.accepted, u.accepted, 'timed/untimed acceptance differs for ' + move);
    assert.equal(t.accepted, r.accepted, 'bridge/raw acceptance differs for ' + move);
    if (!t.accepted) { assert.equal(t.code, u.code); assert.equal(t.code, r.code, 'rejection code'); A.codes[t.code!] = (A.codes[t.code!] ?? 0) + 1; A.rejected++; assert.deepEqual(T.clock(), before, 'rejected move changed bridge clock'); if (JSON.stringify(T.snapshot().ctx.time) !== JSON.stringify(R.state().ctx.time)) A.ctxTimeDivergenceOnReject++; return; }
    A.accepted++;
    if (T.status().endReason === 'timeout' && !R.runtime.hasGameEnded()) {
      // The bridge forfeited at the limit after the engine's own late pass; everything else is the raw result.
      const ts_ = T.snapshot(), rs = R.state();
      assert.deepEqual(ts_.G, rs.G); assert.deepEqual(ts_.ctx.zones, rs.ctx.zones); assert.deepEqual(ts_.ctx.time, rs.ctx.time, 'forfeit changed native time');
      assert.equal(count(T, actor), wasOpening ? 1 : 10); assert.equal(T.status().winner, other(actor)); assert.equal(ts_.ctx._stateID, rs.ctx._stateID + 1);
      if (wasOpening) A.openingLateForfeits++; else A.forfeitsAtLimit10++; stop = true; return;
    }
    if (move === 'passTurn' && before && before.activePlayerId === actor && T.clock().activePlayerId !== actor && ts - before.startedAtMs >= before.players.find((p: any) => p.playerId === actor).remainingMs) A.negativePasses++;
    assert.deepEqual(T.snapshot(), R.state(), 'full timed state differs bridge vs raw after accepted ' + move); A.fullStateEqualAfterAccept++;
    assert.deepEqual(withoutTime(T.snapshot()), withoutTime(N.snapshot()), 'rules state timed vs untimed');
    assert.deepEqual(T.inspect().events, clone(R.runtime.getPublishedGameEvents()), 'events bridge vs raw');
  };
  let guard = 0;
  while (!T.status().ended && !stop && guard++ < 3000) {
    const s: any = T.snapshot(), status = s.ctx.status;
    const actor = s.ctx.priority.pendingChoice?.playerID ?? s.ctx.priority.holder ?? players[0];
    const z = zones(s);
    if (status.gameSegment === 'startingAGame' && rand(12) === 0) { submitAll(pick(players)!, 'concede', {}); if (T.status().ended) A.openingConcessions++; continue; }
    if (rand(5) === 0) { pick([() => submitAll(other(actor), 'passTurn', {}), () => submitAll(actor, 'quest', { cardId: 'instance-' + 'f'.repeat(64) })])!(); continue; }
    if (status.choosingFirstPlayer && T.inspect(actor).moves.includes('chooseWhoGoesFirst')) { submitAll(actor, 'chooseWhoGoesFirst', { playerId: pick(players)! }); continue; }
    const mull = players.find(p => T.inspect(p).moves.includes('alterHand'));
    if (mull) { submitAll(mull, 'alterHand', { cardsToMulligan: [...(z['hand:' + mull] ?? [])].filter(() => rand(3) === 0) }); continue; }
    const options: (() => void)[] = [];
    for (const c of z['hand:' + actor] ?? []) { options.push(() => submitAll(actor, 'putCardIntoInkwell', { cardId: c })); options.push(() => submitAll(actor, 'playCard', { cardId: c, cost: 'standard' })); }
    for (const c of z['play:' + actor] ?? []) { options.push(() => submitAll(actor, 'quest', { cardId: c })); for (const d of z['play:' + other(actor)] ?? []) options.push(() => submitAll(actor, 'challenge', { attackerId: c, defenderId: d })); }
    options.push(() => submitAll(actor, 'passTurn', {}));
    if (rand(40) === 0) options.push(() => submitAll(actor, 'concede', {}));
    pick(options)!();
  }
  assert.ok(T.status().ended, 'game did not finish');
  const st = T.status(), reason = (T.snapshot() as any).ctx.status.reason;
  const expected = reason === 'timeout' ? 'timeout' : /^p[12] conceded$/.test(reason) ? 'concession' : 'normal_win';
  assert.equal(st.endReason, expected, 'end reason for ' + reason);
  A.endReasons[st.endReason] = (A.endReasons[st.endReason] ?? 0) + 1;
  A.games++;
}
for (let g = 0; g < 60; g++) playGame(g);
out.A = A;

// Drive kernel(s) and raw identically through the opening; p1 goes first.
function opening(seed: Buffer, limit: number | undefined, upTo = 3, chooseFirst = 'p1') {
  const K = kernel(seed, 'audit-d13-open', 1000, limit), R = rawRuntime(seed, 'audit-d13-open', 1000, NATIVE);
  const steps: (() => [string, string, Record<string, unknown>])[] = [
    () => [K.status().choosingFirstPlayer, 'chooseWhoGoesFirst', { playerId: chooseFirst }],
    () => [players.find(p => K.inspect(p).moves.includes('alterHand'))!, 'alterHand', { cardsToMulligan: [] }],
    () => [players.find(p => K.inspect(p).moves.includes('alterHand'))!, 'alterHand', { cardsToMulligan: [] }],
  ];
  for (let i = 0; i < upTo; i++) { const [a, m, inp] = steps[i](); assert.equal(K.submit(a, K.status().revision, 1000, 'o' + i, m, clone(inp)).accepted, true); assert.equal(R.submit(a, 1000, 'o' + i, m, clone(inp)).accepted, true); }
  return { K, R };
}

// ---------- B: main-game timeout equals the engine's own late pass ----------
const B = { trials: 0, endedNaturally: 0, early: 0, deltas: {} as Record<string, number> };
for (let i = 0; i < 60; i++) {
  const { K, R } = opening(randomBytes(32), 10);
  let ts = 1000;
  for (let j = rand(4); j > 0; j--) { ts += 1000; const a = K.clock().activePlayerId; assert.equal(K.submit(a, K.status().revision, ts, 'p' + j, 'passTurn', {}).accepted, true); R.submit(a, ts, 'p' + j, 'passTurn', {}); if (K.status().ended) break; }
  if (K.status().ended) continue;
  const a = K.clock().activePlayerId, c0 = count(K, a), delta = pick([0, 1, 777, 60000, 999999])!;
  // Early sweep: refused, nothing changes.
  const snap = K.snapshot();
  assert.throws(() => K.timeout(deadline(K) - 1, 'early' + i)); assert.deepEqual(K.snapshot(), snap); B.early++;
  const at = deadline(K) + delta;
  assert.deepEqual(K.timeout(at, 'to' + i), { accepted: true, code: null });
  assert.equal(R.submit(a, at, 'to' + i, 'passTurn', {}).accepted, true);
  assert.deepEqual(K.snapshot(), R.state(), 'timeout differs from native late pass');
  assert.deepEqual(K.inspect().events, clone(R.runtime.getPublishedGameEvents()));
  assert.equal(count(K, a), c0 + 1);
  if (K.status().ended) { B.endedNaturally++; assert.equal(K.status().endReason, 'normal_win'); }
  else assert.equal(rem(K, a), Math.min(NATIVE.reserveCapMs, NATIVE.resetTimeOnSkipMs + NATIVE.perActionBonusMs + NATIVE.perTurnPassBonusMs));
  B.deltas[delta] = (B.deltas[delta] ?? 0) + 1; B.trials++;
}
out.B = B;

// ---------- C: whole-game limit ----------
const C: Record<string, unknown> = {};
function limitRun(limit: number, consecutive: boolean) {
  const { K, R } = opening(randomBytes(32), limit);
  let ts = 1000, timeouts = 0, step = 0;
  const pass = (a: string) => { ts += 1000; assert.equal(K.submit(a, K.status().revision, ts, 's' + step, 'passTurn', {}).accepted, true); R.submit(a, ts, 's' + step++, 'passTurn', {}); };
  while (!K.status().ended) {
    assert.equal(K.clock().activePlayerId, 'p1');
    const at = deadline(K) + 5000; ts = at;
    assert.equal(K.timeout(at, 't' + step).accepted, true); assert.equal(R.submit('p1', at, 't' + step++, 'passTurn', {}).accepted, true); timeouts++;
    if (K.status().ended) break;
    assert.deepEqual(K.snapshot(), R.state());
    pass('p2'); if (K.status().ended) break;
    if (!consecutive) { pass('p1'); if (K.status().ended) break; pass('p2'); if (K.status().ended) break; }
  }
  const s = K.status(), ks = K.snapshot(), rs = R.state();
  if (s.endReason === 'timeout') { assert.deepEqual(ks.ctx.time, rs.ctx.time); assert.deepEqual(ks.G, rs.G); assert.equal(R.runtime.hasGameEnded(), false); }
  return { limit, consecutive, timeouts, endReason: s.endReason, winner: s.winner, p1Count: count(K, 'p1'), p2Count: count(K, 'p2'), reason: ks.ctx.status.reason };
}
out.C = C;
C.runs = [limitRun(1, true), limitRun(2, false), limitRun(3, false), limitRun(4, true), limitRun(5, true), limitRun(10, true)];
for (const r of C.runs as any[]) {
  if (r.limit <= 5) { assert.equal(r.endReason, 'timeout'); assert.equal(r.winner, 'p2'); assert.equal(r.p1Count, r.limit); assert.equal(r.timeouts, r.limit); }
  else { assert.equal(r.endReason, 'normal_win', 'limit 10 should end by deck-out first'); assert.ok(r.p1Count < 10); }
}

// ---------- D: opening timeouts ----------
const D: any[] = [];
for (const limit of [1, 3, 10]) for (let d = 0; d < 3; d++) for (const chooseFirst of ['p1', 'p2']) {
  const { K } = opening(randomBytes(32), limit, d, chooseFirst);
  const decider = K.clock().activePlayerId, at = deadline(K) + pick([0, 1, 90000])!;
  assert.deepEqual(K.timeout(at, 'ot'), { accepted: true, code: null });
  const s = K.status(); assert.equal(s.ended, true); assert.equal(s.winner, other(decider)); assert.equal(s.endReason, 'timeout');
  assert.equal(count(K, decider), 1); assert.equal(count(K, other(decider)), 0); assert.equal(rem(K, decider), NATIVE.resetTimeOnSkipMs);
  assert.throws(() => K.timeout(at + 1, 'ot2'), 'second timeout after end');
  D.push({ limit, step: d, chooseFirst, decider });
}
// Direct adapter: the decider acts in negative time (live admission refuses this with clock_expired first).
const D2: any[] = [];
for (let d = 0; d < 3; d++) for (const chooseFirst of ['p1', 'p2']) {
  const { K } = opening(randomBytes(32), 3, d, chooseFirst);
  const decider = K.clock().activePlayerId, at = deadline(K) + 1;
  const move = d === 0 ? ['chooseWhoGoesFirst', { playerId: chooseFirst }] : ['alterHand', { cardsToMulligan: [] }];
  const r = K.submit(decider, K.status().revision, at, 'late', move[0] as string, move[1] as Record<string, unknown>);
  const s = K.status();
  D2.push({ step: d, chooseFirst, accepted: r.accepted, ended: s.ended, endReason: s.endReason, deciderCount: count(K, decider), stillActive: K.clock().activePlayerId === decider });
  if (s.ended) { assert.equal(s.endReason, 'timeout'); assert.equal(s.winner, other(decider)); }
  else { assert.equal(K.clock().activePlayerId, decider, 'unended late opening action must keep the decider on the clock'); assert.equal(count(K, decider), 0); }
}
out.D = { openingTimeouts: D.length, directLateOpeningActions: D2 };

// ---------- E: opening concessions ----------
const E: any[] = [];
for (const timed of [true, false]) for (let d = 0; d < 3; d++) for (const who of ['decider', 'waiting']) {
  const seed = randomBytes(32);
  const { K, R } = opening(seed, timed ? 3 : undefined, d);
  const decider = timed ? K.clock().activePlayerId : (d === 0 ? K.status().choosingFirstPlayer : players.find(p => K.inspect(p).moves.includes('alterHand')));
  const c = who === 'decider' ? decider : other(decider);
  assert.ok(K.inspect(c).moves.includes('concede'), 'concede not offered at opening step ' + d);
  const before = timed ? clone(K.clock()) : null;
  assert.deepEqual(K.submit(c, K.status().revision, 1500, 'cc', 'concede', {}), { accepted: true, code: null });
  const s = K.status(); assert.equal(s.ended, true); assert.equal(s.winner, other(c)); assert.equal(s.endReason, 'concession');
  if (timed) { assert.equal(R.submit(c, 1500, 'cc', 'concede', {}).accepted, true); assert.deepEqual(K.snapshot(), R.state()); for (const p of players) assert.equal(count(K, p), before.players.find((x: any) => x.playerId === p).timeoutCount); }
  E.push({ timed, step: d, who });
}
{ // the actor is authoritative: input.playerId cannot concede for the opponent
  const { K } = opening(randomBytes(32), 3, 1);
  assert.equal(K.submit('p1', K.status().revision, 1500, 'forge', 'concede', { playerId: 'p2' }).accepted, true);
  assert.equal(K.status().winner, 'p2'); E.push({ forgedPlayerIdIgnored: true });
}
out.E = E.length;

// ---------- F: forfeitGame is unreachable for players ----------
const F: Record<string, unknown> = {};
for (const [label, upTo] of [['choose', 0], ['mulligan', 1], ['main', 3]] as const) {
  const { K } = opening(randomBytes(32), 3, upTo);
  const snap = K.snapshot();
  for (const p of players) {
    const r = K.submit(p, K.status().revision, 1500, 'ff' + p, 'forfeitGame', { winnerId: p, reason: 'timeout' });
    assert.equal(r.accepted, false); assert.deepEqual(K.snapshot(), snap); F[label + '-' + p] = r.code;
  }
}
const policy = (limit: number) => ({ schemaVersion: 2, id: 'audit-d13', profile: 'qualification', mode: 'dynamic', ...NATIVE, timeoutLimit: limit });
{
  const core = createRecordedCore({ players, startTimestamp: 1000, clock: policy(3) }, randomBytes(32));
  const r = core.facade.submit({ actor: 'p1', expectedRevision: 0, timestamp: 1000, commandId: 'ff', move: 'forfeitGame', input: { winnerId: 'p1', reason: 'timeout' } });
  F.adapterFacade = r; assert.equal(r.accepted, false);
}
out.F = F;

// ---------- G/H: controls never count; pauses ----------
const G: Record<string, unknown> = {};
{
  const { K } = opening(randomBytes(32), 3);
  const late = deadline(K) + 30000;
  K.controlClock({ kind: 'settle', timestamp: late }); assert.equal(count(K, 'p1'), 0);
  K.controlClock({ kind: 'pause', timestamp: late + 10, reason: 'SERVER_RECOVERY' }); assert.equal(count(K, 'p1'), 0);
  assert.throws(() => K.timeout(late + 20, 'paused-timeout'), 'timeout while paused');
  const pc = K.submit('p2', K.status().revision, late + 20, 'pc', 'concede', {}); G.waitingConcedeWhilePaused = pc;
  const ac = K.submit('p1', K.status().revision, late + 20, 'ac', 'concede', {}); G.activeConcedeWhilePaused = ac;
  K.controlClock({ kind: 'resume', timestamp: late + 999999 }); assert.equal(count(K, 'p1'), 0);
  assert.equal(K.timeout(late + 999999, 'after-resume').accepted, true); assert.equal(count(K, 'p1'), 1, 'one timeout after resume, outage not charged as extra');
  K.controlClock({ kind: 'pause', timestamp: late + 1_000_000, reason: 'JUDGE_PAUSE' });
  K.controlClock({ kind: 'reset', timestamp: late + 1_000_000, playerId: 'p2', remainingMs: 1 });
  K.controlClock({ kind: 'resume', timestamp: late + 1_000_000 });
  assert.equal(count(K, 'p1'), 1); assert.equal(count(K, 'p2'), 0); G.controlsCounted = false;
}
out.G = G;

// ---------- I: private replay ----------
const digest = (archive: string) => createHash('sha256').update('completed-private-replay-v1\0').update(archive).digest('hex');
function recorded(limit: number) {
  const core = createRecordedCore({ players, startTimestamp: 1000, clock: policy(limit) }, randomBytes(32));
  const f = core.facade; let rev = 0;
  const sub = (actor: string, move: string, input: Record<string, unknown>, ts = 1000) => { const r = f.submit({ actor, expectedRevision: rev, timestamp: ts, commandId: 'r' + rev, move, input }); if (r.accepted) rev++; return r; };
  return { core, f, sub, rev: () => rev, bump: () => rev++ };
}
const I: Record<string, unknown> = {};
{
  const m = recorded(1), chooser = m.f.status().choosingFirstPlayer;
  assert.equal(m.sub(chooser, 'chooseWhoGoesFirst', { playerId: 'p1' }).accepted, true);
  for (let i = 0; i < 2; i++) { const p = m.core.clock().activePlayerId; assert.equal(m.sub(p, 'alterHand', { cardsToMulligan: [] }).accepted, true); }
  const c = m.core.clock(), at = c.startedAtMs + c.players.find((x: any) => x.playerId === c.activePlayerId).remainingMs + 10;
  assert.deepEqual(m.core.timeout({ expectedRevision: m.rev(), timestamp: at, commandId: 'clock-timeout' }), { accepted: true, code: null });
  const st = m.f.status(); assert.equal(st.endReason, 'timeout'); assert.equal(st.revision, 4, 'pass + forfeit is one logical revision');
  const view = m.core.project({ kind: 'participant', playerId: 'p1' }, 'audit-match'); assert.equal(view.endReason, 'timeout'); assert.equal(view.stateVersion, 4);
  const { archive } = m.f.exportReplay(); assert.equal(verifyCompletedReplay(archive, digest(archive)).verified, true);
  const data = JSON.parse(archive), idx = data.commands.findIndex((x: any) => x.timeout);
  const tamper: Record<string, (d: any) => void> = {
    endReason: d => { d.final.status.endReason = 'concession'; },
    winner: d => { d.final.status.winner = 'p1'; },
    timeoutResult: d => { d.commands[idx].result = { accepted: false, code: 'NO_LEGAL_DEFAULT' }; },
    timeoutTimestamp: d => { d.commands[idx].timeout.timestamp -= 5; },
    dropTimeout: d => { d.commands.splice(idx, 1); },
    playerForfeit: d => { d.commands[idx] = { command: { actor: 'p2', expectedRevision: 3, timestamp: at, commandId: 'x', move: 'forfeitGame', input: { winnerId: 'p2', reason: 'timeout' } }, result: { accepted: true, code: null }, stateHash: d.commands[idx].stateHash, randomOutcomes: [] }; },
  };
  for (const [name, fn] of Object.entries(tamper)) { const d = clone(data); fn(d); const a = canonical(d); assert.throws(() => verifyCompletedReplay(a, digest(a)), name); I['rejected:' + name] = true; }
}
{
  const m = recorded(3), chooser = m.f.status().choosingFirstPlayer;
